local function newObject(o, class)
    class.__index = class
    return setmetatable(o, class)
end

local s_vsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

attribute vec2 position;
varying vec2 textureCoord;

void main()
{
    textureCoord = position*.5+.5;
    gl_Position = vec4(position, 0.,1.);
}
]]

local s_fsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif // GL_FRAGMENT_PRECISION_HIGH

uniform sampler2D inputImageTexture;
varying vec2 textureCoord;

const float SAMPLES = 12.0;
uniform float iTime;
uniform float strength;
uniform float density;
uniform vec2 glowCenter;

float hash(vec2 p){
    return fract(sin(dot(p, vec2(41, 289)))*45758.5453);
}

vec3 lOff(){
    vec2 u = sin(glowCenter);
    mat2 a = mat2(u, -u.y, u.x);
    vec3 l = normalize(vec3(1.5, 1., -0.5));
    l.xz = a * l.xz;
    l.xy = a * l.xy;
    return l;
}

void main() {
    vec2 uv0 = textureCoord;
    vec2 uv = textureCoord;
    float decay = 0.97;
    float weight = 0.1;
    vec3 l = lOff();
    vec2 tuv =  uv - glowCenter - l.xy * 0.01;
    vec2 dTuv = tuv * density/SAMPLES;
    vec4 col = texture2D(inputImageTexture, uv.xy)*strength;
    uv += dTuv*(hash(uv.xy + fract(iTime)) * 2.0 - 1.0);

    for(float i = 0.0; i < SAMPLES; i++){
        uv -= dTuv;
        col += texture2D(inputImageTexture, uv) * weight;
        weight *= decay;
    }

    col *= (1.0 - dot(tuv, tuv) * 0.75);
    vec4 resultColor = sqrt(smoothstep(0.0, 1.0, col));
    resultColor.a = texture2D(inputImageTexture, uv0).a;
    gl_FragColor = resultColor;
}
]]

EdgeGlow = {}

 local textureDrawer = nil
function EdgeGlow:matchWithId(effectId)
    return 'KFM KSkr EdgeGlow' == effectId
end

function EdgeGlow.createWithId(effectId)
    if not EdgeGlow:matchWithId(effectId) then
        return nil
    end
    local o = {
        program = {},
        vertexBuffer = 0,
        uniformTime = -1,
        glowIntensity = 0.0,
        glowCenter = {0.0, 0.0},
        glowDensity = 0.0,
        currentWidth = 0,
        currentHeight = 0
    }
    o = newObject(o, EdgeGlow)
    o:init()
    return o;
end

function EdgeGlow:init()
    local buffer = {}
    glGenBuffers(1,buffer)
    self.vertexBuffer = buffer[1]
    local vertices = {-1,-1,1,-1,-1,1,1,1}
    local verticesData = CGE.FloatBuffer:alloc(#vertices)
    verticesData:put(#vertices, vertices, 0)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glBufferData(GL_ARRAY_BUFFER, #vertices, verticesData:position(0), GL_STATIC_DRAW)

    self.program = CGE.ProgramObject()
    self.program:bindAttribLocation('position', 0)
    self.program:initWithShaderStrings(s_vsh, s_fsh)
    self.program:bind()
    self.program:sendUniformi('inputImageTexture', 0)
    self.uniformTime = self.program:uniformLocation('iTime')
end

function EdgeGlow:updateValue(index, val1, val2, val3)
    self.program:bind()
    if index == 1 then
        self.glowCenter = {val1, val2}
    elseif index == 2 then
        self.glowIntensity = val1 / 100.0
        self.program:sendUniformf('strength', self.glowIntensity)
    elseif index == 3 then
        self.glowDensity = val1 / 100.0
        self.program:sendUniformf('density', self.glowDensity)
    end
end

function EdgeGlow:customResize(width, height)
    self.currentWidth = width
    self.currentHeight = height
end

function EdgeGlow:onDestroy()
    glDeleteBuffers(1, {self.vertexBuffer})
end

function EdgeGlow:updateTimeAndFrame(time)
    if self.uniformTime >= 0  then
        self.program:bind()
        glUniform1f(self.uniformTime, time)
    end
end

function EdgeGlow:render(outFBO, inputTex)
    local viewportSize = {}
    glGetIntegerv(GL_VIEWPORT, 4, viewportSize)
    self:customResize(viewportSize[3], viewportSize[4])

    glBindFramebuffer(GL_FRAMEBUFFER, outFBO)
    self.program:bind()
    self.program:sendUniformf('glowCenter', self.glowCenter[1] / self.currentWidth, self.glowCenter[2] / self.currentHeight)
    
    -- CGE_LOG_ERROR('********************' .. self.glowCenter[1] .. '&' .. self.currentWidth .. '*' .. self.glowCenter[2] .. '*' .. self.currentHeight)
    glBindBuffer(GL_ARRAY_BUFFER, self.vertexBuffer)
    glEnableVertexAttribArray(0)
    glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, 0)
    glActiveTexture(GL_TEXTURE0)
    glBindTexture(GL_TEXTURE_2D, inputTex)
    glDrawArrays(GL_TRIANGLE_STRIP, 0, 4)
end